# owner: platform
"""Absence notices for parents, from attendance marks."""

from typing import List
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date

def vet_marks(student: Student, marks: List[Mark]) -> None:
    """Refuse marks that belong to someone else."""
    seen = {mark.student_id for mark in marks}
    others = sorted(seen - {student.student_id})
    if others:
        names = ", ".join(others)
        raise ValueError(f"marks for others: {names}")

def count_phrase(days: List[date]) -> str:
    """'1 day' or '3 days'."""
    noun = "day" if len(days) == 1 else "days"
    return f"{len(days)} {noun}"

def format_day(day: date) -> str:
    return f"{day:%B} {day.day}, {day.year}"

def join_days(days: List[date]) -> str:
    """Days as prose: 'A', 'A and B' or 'A, B, and C'."""
    names = [format_day(day) for day in days]
    if len(names) < 3:
        return " and ".join(names)
    return f"{', '.join(names[:-1])}, and {names[-1]}"

def build_notice(student: Student, days: List[date]) -> str:
    """One sentence: the name, the count and the dates."""
    name = f"{student.first_name} {student.last_name}"
    count = count_phrase(days)
    sentence = f"{name} was marked absent {count}"
    return f"{sentence}: {join_days(days)}."

def notice_for(student: Student, marks: List[Mark]) -> str:
    """Notice for a parent listing the absent days."""
    vet_marks(student, marks)
    days = days_missed(marks)
    if not days:
        raise ValueError("no absences to report")
    return build_notice(student, days)
